const localOf=(A,v)=>[V.dot(v,A.x),V.dot(v,A.y),V.dot(v,A.z)],worldOf=(A,l)=>V.add(V.add(V.scale(A.x,l[0]),A.y,l[1]),A.z,l[2]);
