const frontK=ang=>1-smooth((ang-FRONT_W[0])/(FRONT_W[1]-FRONT_W[0]));
/* Рамка позвонка на высоте h (L5…L1): см. VERT_LEVELS. Позвонки — твёрдые тела, кожа над ними — по своей схеме (spineFrame). */
