  const f=best.f,lx=V.dot(best.off,f.x),lz=V.dot(best.off,f.z),[w,a,b]=sectionAt(best.s.h);
  const k1=best.s.f.front?frontK(Math.atan2(Math.abs(lx)/w,lz/(lz>=0?a:b))):0;if(Math.abs(k1-kf)<.01&&it)break;
