 const lx=(a[0][0]*dx+a[0][1]*dy+a[0][2]*dz)/r[0],ly=(a[1][0]*dx+a[1][1]*dy+a[1][2]*dz)/r[1],lz=(a[2][0]*dx+a[2][1]*dy+a[2][2]*dz)/r[2];
