   const b=ortho(back,axis),viaEl=V.dot(V.cross(down,F.y),axis),sg=(palmar(down)&&Math.abs(viaEl)>.15?viaEl:V.dot(V.cross(down,b),axis))>=0?1:-1,w=V.scale(V.cross(axis,down),sg);
