    const nrm = pts0.slice(1).map((p, j) => { const c = cs.reduce((a, q) => V.dist(V.mix(pts0[j], p, .5), q.c) < V.dist(V.mix(pts0[j], p, .5), a.c) ? q : a); return V.unit(V.perp(V.sub(V.mix(pts0[j], p, .5), c.c), axis)); });
