    if (e.from) return hands.length > 1 ? [{ handle: hands[0] }, { ring: e.from, mountTo: e.mountTo }, { handle: hands[1] }] : [{ handle: hands[0] }, { ring: e.from, mountTo: e.mountTo }, { handle: hands[0] }];
