  return { kind, pl, alpha: al, psi, viol, contact: pl.to3(Tc), contact2: Tc, nl, momentArm: p, camLen, segs, wraps, block, s,
    L, pts3: pts.map(pl.to3), leave3: pl.to3(arrive), camO: pl.O, u, v };
