  const SUP = { MAX: 4, GAP_MAX: 3, PRESS: .5, RAMP: 3, GAP_VERTS: 250, FOOT_REST: 60, LEN: 24, HEEL_Z: -2.5, HEEL_MARGIN: 1, HEEL: 1000, EDGE: .04 };
